import { BinaryWriter } from "@bufbuild/protobuf/wire";
import { Code, ConnectError } from "@connectrpc/connect";
import { describe, expect, it } from "vitest";
import { ERROR_REASON_RATE_LIMITED, getErrorInfo, getErrorMessage, getRetryAfterSeconds, hasErrorReason } from "@/lib/error";

function encodeErrorInfo(reason: string, domain: string, metadata: Record<string, string>): Uint8Array {
  const writer = new BinaryWriter();
  writer.tag(1, 2).string(reason);
  writer.tag(2, 2).string(domain);
  for (const [key, value] of Object.entries(metadata)) {
    const entry = new BinaryWriter();
    entry.tag(1, 2).string(key);
    entry.tag(2, 2).string(value);
    writer.tag(3, 2).bytes(entry.finish());
  }
  return writer.finish();
}

function rateLimitError(retryAfterSeconds: string): ConnectError {
  // Incoming details arrive as raw type-url and bytes pairs; mirror that shape.
  const error = new ConnectError("too many requests, try again later", Code.ResourceExhausted);
  error.details.push(
    {
      type: "google.rpc.ErrorInfo",
      value: encodeErrorInfo(ERROR_REASON_RATE_LIMITED, "memos.api", {
        scope: "signin_ip",
        retry_after_seconds: retryAfterSeconds,
      }),
    },
    { type: "google.rpc.RetryInfo", value: new Uint8Array([10, 2, 8, 42]) },
  );
  return error;
}

describe("ErrorInfo decoding", () => {
  it("reads reason, domain and metadata from the detail", () => {
    const info = getErrorInfo(rateLimitError("42"));
    expect(info).toEqual({
      reason: ERROR_REASON_RATE_LIMITED,
      domain: "memos.api",
      metadata: { scope: "signin_ip", retry_after_seconds: "42" },
    });
    expect(hasErrorReason(rateLimitError("42"), ERROR_REASON_RATE_LIMITED)).toBe(true);
  });

  it("turns a rate-limit refusal into a wait message", () => {
    expect(getRetryAfterSeconds(rateLimitError("42"))).toBe(42);
    expect(getErrorMessage(rateLimitError("42"))).toBe("Too many requests. Try again in 42s.");
    expect(getErrorMessage(rateLimitError("300"))).toBe("Too many requests. Try again in 5 min.");
  });

  it("leaves other errors alone", () => {
    const plain = new ConnectError("nope", Code.InvalidArgument);
    expect(getErrorInfo(plain)).toBeUndefined();
    expect(getRetryAfterSeconds(plain)).toBeUndefined();
    expect(getErrorMessage(plain)).toBe("nope");
    expect(getErrorInfo(new Error("x"))).toBeUndefined();
  });
});
import { BinaryWriter } from "@bufbuild/protobuf/wire";
import { Code, ConnectError } from "@connectrpc/connect";
import { describe, expect, it } from "vitest";
import { errorService } from "@/components/MemoEditor/edit/services/errorService";
import { ERROR_REASON_QUOTA_EXCEEDED, getErrorMessage, getRetryAfterSeconds } from "@/lib/error";

function quotaError(metadata: Record<string, string>): ConnectError {
  const writer = new BinaryWriter();
  writer.tag(1, 2).string(ERROR_REASON_QUOTA_EXCEEDED);
  writer.tag(2, 2).string("memos.api");
  for (const [key, value] of Object.entries(metadata)) {
    const entry = new BinaryWriter();
    entry.tag(1, 2).string(key);
    entry.tag(2, 2).string(value);
    writer.tag(3, 2).bytes(entry.finish());
  }
  const error = new ConnectError("quota exceeded", Code.ResourceExhausted);
  error.details.push({ type: "google.rpc.ErrorInfo", value: writer.finish() });
  return error;
}

describe("usage limit refusals", () => {
  it("names the memo limit", () => {
    const error = quotaError({ metric: "MEMO_COUNT", limit: "1000", usage: "1000", usage_limit: "usageLimits/default-memos" });
    expect(getErrorMessage(error)).toBe("You have reached your limit of 1000 memos. Delete memos to create new ones.");
  });

  it("names the storage limit and the current usage", () => {
    const error = quotaError({ metric: "STORAGE_BYTES", limit: String(1024 ** 3), usage: String(1000 * 1024 ** 2) });
    expect(getErrorMessage(error)).toBe("This upload would exceed your storage limit of 1.0 GB. You are using 1000.0 MB.");
  });

  it("names the per-file limit", () => {
    const error = quotaError({ metric: "UPLOAD_BYTES", limit: String(10 * 1024 ** 2), usage: String(20 * 1024 ** 2) });
    expect(getErrorMessage(error)).toBe("This file is larger than your limit of 10.0 MB per file.");
  });

  it("names the content limit and reaches the editor's error message", () => {
    const error = quotaError({ metric: "MEMO_CONTENT_BYTES", limit: "8192", usage: "8193" });
    const message = "This memo is larger than your limit of 8.0 KB per memo. Shorten the content to save it.";
    expect(getErrorMessage(error)).toBe(message);
    expect(errorService.getErrorMessage(error)).toBe(message);
  });

  it("is not a rate limit, so it carries no wait", () => {
    const error = quotaError({ metric: "MEMO_COUNT", limit: "1", usage: "1" });
    expect(getRetryAfterSeconds(error)).toBeUndefined();
  });

  it("reaches the editor's own error messages", () => {
    const error = quotaError({ metric: "UPLOAD_BYTES", limit: String(1024 ** 2), usage: String(2 * 1024 ** 2) });
    expect(errorService.getErrorMessage(error)).toBe("This file is larger than your limit of 1.0 MB per file.");
  });
});
